scan_linter_check.script:
(function(engine) {
    global.EcsGlideRecord.runBulkCheck(engine, {
        ruleId: 'SN-GR-003-R',
        tier: 'review',
        bulkMethod: 'updateMultiple',
        perRecordMethod: 'update',
        title: 'GlideRecord update whose query conditions could not be verified',
        recommendation: 'Confirm the conditions always restrict the update: validate run-time values (empty or ' +
            'undefined values and invalid field names may widen the query), avoid adding conditions on only some ' +
            'code paths, and check the affected count before updating. Mute this finding with a reason once reviewed.'
    });
})(engine);
